 const label=(id:string)=>models.find(m=>m.id===id)?.label??id;
</script>
<svelte:head><title>お問い合わせのAI設定 | Autumn Book</title></svelte:head>
<section class="ai-settings"><a class="back" href="/admin/inquiries">← お問い合わせ</a><header><h1>お問い合わせのAI設定</h1><span>全施設共通</span></header>
 <section class="settings-card" aria-label="共通AIモデル設定"><div class="card-heading"><h2>AIモデル</h2><span>現在：{label(data.settings.effective_model)}</span></div>
